const base='https://mapservices.weather.noaa.gov/tropical/rest/services/tropical/NHC_tropical_weather_summary/MapServer';
const layers=[
 {id:1,kind:'2day',name:'2-Day Outlook'},
 {id:2,kind:'7day',name:'7-Day Outlook'},
 {id:33,kind:'7motion',name:'7-Day Development Motion'},
 {id:3,kind:'7region',name:'7-Day Development Region'},
 {id:5,kind:'points',name:'Forecast Points'},
 {id:6,kind:'track',name:'Forecast Track'},
 {id:7,kind:'cone',name:'Forecast Cone'},
 {id:8,kind:'warning',name:'Watch-Warning'},
 {id:15,kind:'wind',name:'Forecast Wind Radii'}
];
msg.payload=layers.map(l=>({
 url:`${base}/${l.id}/query?where=1%3D1&outFields=*&returnGeometry=true&f=geojson`,
 nhcLayer:l.id,
 nhcKind:l.kind,
 nhcName:l.name
}));
node.status({fill:'blue',shape:'dot',text:'9 NOAA layers queued'});
return msg;

if(!msg.payload || !msg.payload.url){ node.error('NOAA request missing payload.url',msg); return null; }
msg.url=msg.payload.url;
msg.nhcLayer=msg.payload.nhcLayer;
msg.nhcKind=msg.payload.nhcKind;
msg.nhcName=msg.payload.nhcName;
return msg;

const fc=msg.payload;
const count=fc&&Array.isArray(fc.features)?fc.features.length:0;
msg.nhcResult={layer:msg.nhcLayer,kind:msg.nhcKind,name:msg.nhcName,status:msg.statusCode,features:count};
node.status({fill:count?'green':'yellow',shape:'dot',text:`${msg.nhcName}: ${count} features`});
return msg;

const fc=msg.payload;
if(!fc||fc.type!=='FeatureCollection')return null;

const RED=-65536;
const ORANGE=-23296;
const YELLOW=-256;
const GREEN=-16711936;
const FRED=1073741824;
const FORANGE=1073758208;
const FYELLOW=1073742080;
const NONE=0;

function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');}
function safe(v){return String(v??'NHC').replace(/[^A-Za-z0-9_.:-]/g,'_').slice(0,70);}
function time(){return new Date().toISOString();}
function stale(){return new Date(Date.now()+20*60000).toISOString();}
function prob(p){return p.prob7day??p.prob2day??p.probability??p.prob??'N/A';}
function pct(v){const n=parseInt(String(v));return Number.isFinite(n)?n:0;}

function point(uid,call,lat,lon,remarks,color,type='u-d-p'){
 const t=time();
 return `<?xml version="1.0" encoding="UTF-8"?>
<event version="2.0" uid="${esc(uid)}" type="${type}" how="m-g" time="${t}" start="${t}" stale="${stale()}"><point lat="${Number(lat)}" lon="${Number(lon)}" hae="0" ce="9999999" le="9999999"/><detail><contact callsign="${esc(call)}"/><remarks>${esc(remarks)}</remarks><color argb="${color}"/><labels_on value="true"/><marti><dest name="NWS"/></marti></detail></event>
`;
}

function coords(g){
 if(!g)return[];
 if(g.type==='LineString')return[g.coordinates];
 if(g.type==='MultiLineString')return g.coordinates||[];
 if(g.type==='Polygon')return g.coordinates||[];
 if(g.type==='MultiPolygon'){const a=[];for(const p of g.coordinates||[])for(const r of p||[])a.push(r);return a;}
 return[];
}

function shape(uid,call,c,remarks,closed,stroke,fill){
 if(!Array.isArray(c)||c.length<2)return null;
 const pts=c.filter(p=>Array.isArray(p)&&p.length>=2).map(p=>[Number(p[1]),Number(p[0])]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1]));
 if(pts.length<2)return null;
 if(closed){const a=pts[0],b=pts[pts.length-1];if(a[0]!==b[0]||a[1]!==b[1])pts.push(a);}
 const links=pts.map(p=>`<link point="${p[0]},${p[1]},0"/>`).join('');
 const t=time();
 return `<?xml version="1.0" encoding="UTF-8"?>
<event version="2.0" uid="${esc(uid)}" type="u-d-f" how="m-g" time="${t}" start="${t}" stale="${stale()}"><point lat="${pts[0][0]}" lon="${pts[0][1]}" hae="0" ce="9999999" le="9999999"/><detail><contact callsign="${esc(call)}"/>${links}<strokeColor value="${stroke}"/><strokeWeight value="4"/><fillColor value="${fill}"/><remarks>${esc(remarks)}</remarks><labels_on value="true"/><marti><dest name="NWS"/></marti></detail></event>
`;
}

const out=[];
const _seq={};
function nextKey(k){_seq[k]=(_seq[k]||0)+1;return _seq[k];}
const features=fc.features||[];
const kind=msg.nhcKind;

for(let i=0;i<features.length;i++){
 const f=features[i]||{};
 const p=f.properties||{};
 const g=f.geometry||{};
 const basin=p.basin||'NHC';
 const oid = nextKey(kind + '|' + basin + '|' + (p.stormname || '')); // stable: Nth feature for this storm/layer (NOAA objectids change every advisory)

 if(kind==='2day'&&g.type==='Point'){
  const lat=Number(g.coordinates[1]),lon=Number(g.coordinates[0]);
  if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;
  const pr=p.prob2day||'N/A';
  const n=pct(pr);
  const color=n>=70?RED:n>=40?YELLOW:GREEN;
  const remarks=`NOAA NHC 2-Day Outlook | Basin ${basin} | Probability ${pr} | Risk ${p.risk2day||'N/A'}`;
  out.push({payload:point(`NHC-2DAY-${safe(basin)}-${oid}`,`NHC ${basin} 2D ${pr}`,lat,lon,remarks,color),nhc:{product:'2-Day Outlook',basin,probability:pr,lat,lon}});
 }

 if(kind==='7day'&&g.type==='Point'){
  const lat=Number(g.coordinates[1]),lon=Number(g.coordinates[0]);
  if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;
  const pr=p.prob7day||'N/A';
  const n=pct(pr);
  const color=n>=70?RED:n>=40?ORANGE:YELLOW;
  const remarks=`NOAA NHC 7-Day Outlook | Basin ${basin} | Probability ${pr} | Risk ${p.risk7day||'N/A'}`;
  out.push({payload:point(`NHC-7DAY-${safe(basin)}-${oid}`,`NHC ${basin} 7D ${pr}`,lat,lon,remarks,color),nhc:{product:'7-Day Outlook',basin,probability:pr,lat,lon}});
 }

 if(kind==='7region'){
  const pr=p.prob7day||'N/A';
  const n=pct(pr);
  const stroke=n>=70?RED:n>=40?ORANGE:YELLOW;
  const fill=n>=70?FRED:n>=40?FORANGE:FYELLOW;
  const rs=coords(g);
  for(let j=0;j<rs.length;j++){
   const uid=`NHC-7REGION-${safe(basin)}-${oid}-${j}`;
   const remarks=`NOAA NHC 7-Day Development Region | Basin ${basin} | Probability ${pr}`;
   const cot=shape(uid,`NHC ${basin} DEV ${pr}`,rs[j],remarks,true,stroke,fill);
   if(cot)out.push({payload:cot,nhc:{product:'7-Day Development Region',basin,probability:pr}});
  }
 }

 if(kind==='7motion'){
  const pr=p.prob7day||'N/A';
  const n=pct(pr);
  const stroke=n>=70?RED:n>=40?ORANGE:YELLOW;
  for(let j=0;j<coords(g).length;j++){
   const cot=shape(`NHC-7MOTION-${safe(basin)}-${oid}-${j}`,`NHC ${basin} MOTION ${pr}`,coords(g)[j],`NOAA NHC 7-Day Development Motion | Basin ${basin} | Probability ${pr}`,false,stroke,NONE);
   if(cot)out.push({payload:cot,nhc:{product:'7-Day Development Motion',basin,probability:pr}});
  }
 }

 if(kind==='points'&&g.type==='Point'){
  const lat=Number(g.coordinates[1]),lon=Number(g.coordinates[0]);
  if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;
  const storm=p.stormname||'NHC STORM';
  const tau=Number(p.fcstprd??0);
  const label=tau===0?'CURRENT':`+${tau}H`;
  const wind=p.maxwind??'';
  const gust=p.gust??'';
  const remarks=`NOAA NHC Forecast Point | ${storm} | ${label}${wind!==''?' | Wind '+wind+' kt':''}${gust!==''?' | Gust '+gust+' kt':''}`;
  out.push({payload:point(`NHC-POINT-${safe(basin)}-${safe(storm)}-${tau}`,`${storm} ${label}`,lat,lon,remarks,RED,'a-h-G'),nhc:{product:'Forecast Point',basin,storm,tau,lat,lon,wind,gust}});
 }

 if(kind==='track'){
  const storm=p.stormname||'NHC STORM';
  for(let j=0;j<coords(g).length;j++){
   const cot=shape(`NHC-TRACK-${safe(basin)}-${safe(storm)}-${oid}-${j}`,`${storm} FORECAST TRACK`,coords(g)[j],`NOAA NHC Forecast Track | ${storm} | Basin ${basin}`,false,RED,NONE);
   if(cot)out.push({payload:cot,nhc:{product:'Forecast Track',basin,storm}});
  }
 }

 if(kind==='cone'){
  const storm=p.stormname||'NHC STORM';
  for(let j=0;j<coords(g).length;j++){
   const cot=shape(`NHC-CONE-${safe(basin)}-${safe(storm)}-${oid}-${j}`,`${storm} FORECAST CONE`,coords(g)[j],`NOAA NHC Forecast Cone | ${storm} | Basin ${basin}`,true,RED,FRED);
   if(cot)out.push({payload:cot,nhc:{product:'Forecast Cone',basin,storm}});
  }
 }

 if(kind==='warning'){
  const storm=p.stormname||'NHC';
  const ww=p.tcww||'WATCH/WARNING';
  const stroke=ww==='HWR'||ww==='HWA'?RED:ww==='TWR'? -16776961:YELLOW;
  for(let j=0;j<coords(g).length;j++){
   const cot=shape(`NHC-WW-${safe(basin)}-${safe(storm)}-${oid}-${j}`,`${storm} ${ww}`,coords(g)[j],`NOAA NHC ${ww} | ${storm} | Basin ${basin}`,false,stroke,NONE);
   if(cot)out.push({payload:cot,nhc:{product:'Watch-Warning',basin,storm,warning:ww}});
  }
 }

 if(kind==='wind'){
  const storm=p.stormname||'NHC STORM';
  for(let j=0;j<coords(g).length;j++){
   const cot=shape(`NHC-WIND-${safe(basin)}-${safe(storm)}-${oid}-${j}`,`${storm} WIND RADII`,coords(g)[j],`NOAA NHC Forecast Wind Radii | ${storm} | Basin ${basin}`,true,ORANGE,FORANGE);
   if(cot)out.push({payload:cot,nhc:{product:'Forecast Wind Radii',basin,storm}});
  }
 }
}

// Remove objects that were sent last poll for this layer but are gone now
// (storm dissipated, forecast point dropped, fewer wind radii, etc.)
const curUids=out.map(m=>{const r=/uid="([^"]+)"/.exec(m.payload);return r?r[1]:null;}).filter(Boolean);
const ctxKey='nhcUids_'+kind;
const prevUids=flow.get(ctxKey)||[];
const curSet=new Set(curUids);
const gone=prevUids.filter(u=>!curSet.has(u));
for(const u of gone){
 const t=time();
 const st=new Date(Date.now()+60000).toISOString();
 out.push({payload:`<?xml version="1.0" encoding="UTF-8"?>\n<event version="2.0" uid="NHC-DEL-${esc(u)}" type="t-x-d-d" how="h-g-i-g-o" time="${t}" start="${t}" stale="${st}"><point lat="0" lon="0" hae="0" ce="9999999" le="9999999"/><detail><link uid="${esc(u)}" relation="none" type="none"/><__forcedelete/></detail></event>\n`,nhc:{product:'Delete',uid:u}});
}
flow.set(ctxKey,curUids);
out.forEach(m=>{m.parts=msg.parts;m.nhcName=msg.nhcName;m.nhcKind=kind;});

node.status({fill:curUids.length?'green':'yellow',shape:curUids.length?'dot':'ring',text:`${msg.nhcName}: ${curUids.length} CoT, ${gone.length} removed`});
return out.length?[out]:null;

// NHC EVENT SUMMARY
// Counts events for the CURRENT poll only.
// Passes the original CoT message through unchanged.

const layer = msg.nhcName || msg.nhcKind || "Unknown";

// The nine NOAA requests are split messages.
// Each poll gets a new msg.parts.id.
const pollId = msg.parts && msg.parts.id
    ? msg.parts.id
    : null;

let state = flow.get("nhcCurrentPoll");

// Start a new counter when a new poll begins.
if (!state || state.pollId !== pollId) {
    state = {
        pollId: pollId,
        total: 0,
        layers: {}
    };
}

// Count this event.
state.total += 1;

if (!state.layers[layer]) {
    state.layers[layer] = 0;
}

state.layers[layer] += 1;

flow.set("nhcCurrentPoll", state);

// Add summary information without changing the CoT payload.
msg.nhcSummary = {
    pollId: state.pollId,
    layer: layer,
    layerCount: state.layers[layer],
    totalEventsThisPoll: state.total
};

// Node status.
node.status({
    fill: "green",
    shape: "dot",
    text: `NHC: ${state.total} events this poll`
});

// Pass original CoT unchanged to TAK.
return msg;
